document.addEventListener("DOMContentLoaded",function(){const e=new IntersectionObserver(t=>{t.forEach(t=>{if(t.isIntersecting){const n=t.target;n.dataset.src&&(n.src=n.dataset.src,n.classList.remove("lazy")),e.unobserve(n)}})},{rootMargin:"50px 0px",threshold:.01});document.querySelectorAll("img[data-src]").forEach(t=>{e.observe(t)});const t=new IntersectionObserver(e=>{e.forEach(e=>{if(e.isIntersecting){const n=e.target;n.dataset.endpoint&&fetch(n.dataset.endpoint).then(e=>e.text()).then(e=>{n.innerHTML=e}),t.unobserve(n)}})});document.querySelectorAll("[data-lazy-section]").forEach(e=>{t.observe(e)})});